/**
 * SMART CITY LOGISTICS – CARPOOLING SYSTEM
 * C++ Backend Data Structures & Algorithms Interactive Engine
 * Featuring 3D Perspective Tilt Physics, Dijkstra Shortest Path,
 * Queues, Circular Buffers, Linked Lists, BST, Hash Table, & Stack Undo.
 */

// ==========================================
// 1. DATA STRUCTURES DEFINITIONS & STATE
// ==========================================

// City Map Nodes (Intersections & Hubs)
const CITY_NODES = [
  { id: 'ALPHA', name: 'Alpha Tech Core', x: -160, y: -70, z: 20 },
  { id: 'HARBOR', name: 'Cyber Harbor', x: -80, y: 110, z: -15 },
  { id: 'METRO', name: 'Neo Metro Center', x: 0, y: 0, z: 40 },
  { id: 'SKYPORT', name: 'Skyport Hub', x: 130, y: -90, z: 30 },
  { id: 'QUANTUM', name: 'Quantum Park', x: 90, y: 100, z: -10 },
  { id: 'HORIZON', name: 'Horizon District', x: 200, y: 30, z: 5 }
];

// Graph Adjacency List with Edge Distances/Weights (km)
const CITY_EDGES = [
  { u: 'ALPHA', v: 'METRO', weight: 8 },
  { u: 'ALPHA', v: 'HARBOR', weight: 12 },
  { u: 'HARBOR', v: 'METRO', weight: 6 },
  { u: 'HARBOR', v: 'QUANTUM', weight: 14 },
  { u: 'METRO', v: 'SKYPORT', weight: 10 },
  { u: 'METRO', v: 'QUANTUM', weight: 7 },
  { u: 'SKYPORT', v: 'HORIZON', weight: 9 },
  { u: 'QUANTUM', v: 'HORIZON', weight: 11 }
];

// C++ Engine State Emulation
class SmartCityEngine {
  constructor() {
    // Array / Spatial Matrix
    this.nodes = CITY_NODES;
    this.edges = CITY_EDGES;

    // FIFO Queue for Incoming Passengers
    this.passengerQueue = [];

    // Circular Queue (Array capacity 5)
    this.circularCap = 5;
    this.circularQueue = new Array(this.circularCap).fill(null);
    this.circularFront = 0;
    this.circularRear = 0;
    this.circularSize = 0;

    // Singly Linked List: Driver Catalog
    this.driverHead = null; // { id, name, location, seats, originalSeats, next }
    this.driverCount = 0;

    // Hash Table for Driver ID Lookup (Chaining with 6 buckets)
    this.hashBucketSize = 6;
    this.hashTable = Array.from({ length: this.hashBucketSize }, () => []);

    // Doubly Linked List: Active Confirmed Rides
    this.activeRidesHead = null; // { rideId, passenger, driver, route, dist, prev, next }
    this.activeRidesTail = null;
    this.activeRideCount = 0;

    // Binary Search Tree (BST) of Rides sorted by Ride ID
    this.bstRoot = null;

    // Stack (LIFO): Undo History
    this.undoStack = [];

    this.idCounter = {
      driver: 101,
      ride: 501,
      passenger: 201
    };
  }

  // --- Graph: Dijkstra Shortest Path with Min-Heap trace ---
  runDijkstra(startId, targetId) {
    const adj = {};
    CITY_NODES.forEach(n => { adj[n.id] = []; });
    CITY_EDGES.forEach(e => {
      adj[e.u].push({ node: e.v, weight: e.weight });
      adj[e.v].push({ node: e.u, weight: e.weight });
    });

    const dist = {};
    const prev = {};
    CITY_NODES.forEach(n => {
      dist[n.id] = Infinity;
      prev[n.id] = null;
    });

    dist[startId] = 0;

    // Min-Heap emulation [ [distance, nodeId] ]
    const minHeap = [[0, startId]];
    const traceSteps = [];

    while (minHeap.length > 0) {
      // Sort heap ascending (Min-Heap extract min)
      minHeap.sort((a, b) => a[0] - b[0]);
      const [d, u] = minHeap.shift();

      traceSteps.push({
        extracted: u,
        dist: d,
        heapSnapshot: minHeap.map(item => ({ node: item[1], dist: item[0] }))
      });

      if (u === targetId) break;
      if (d > dist[u]) continue;

      for (const edge of adj[u]) {
        const v = edge.node;
        const newDist = dist[u] + edge.weight;
        if (newDist < dist[v]) {
          dist[v] = newDist;
          prev[v] = u;
          minHeap.push([newDist, v]);
        }
      }
    }

    // Reconstruct path
    const path = [];
    let curr = targetId;
    if (dist[targetId] !== Infinity) {
      while (curr) {
        path.unshift(curr);
        curr = prev[curr];
      }
    }

    return {
      path,
      totalCost: dist[targetId] === Infinity ? -1 : dist[targetId],
      traceSteps
    };
  }

  // --- Queue: FIFO Passenger Pipeline ---
  enqueuePassenger(name, pickup, drop) {
    const passenger = {
      id: `P-${this.idCounter.passenger++}`,
      name,
      pickup,
      drop,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    this.passengerQueue.push(passenger);
    return passenger;
  }

  dequeuePassenger() {
    return this.passengerQueue.shift() || null;
  }

  // --- Circular Queue (Capacity 5) ---
  circularEnqueue(item) {
    if (this.circularSize === this.circularCap) {
      return { success: false, reason: 'OVERFLOW: Circular buffer is full (5/5).' };
    }
    this.circularQueue[this.circularRear] = item;
    this.circularRear = (this.circularRear + 1) % this.circularCap;
    this.circularSize++;
    return { success: true };
  }

  circularDequeue() {
    if (this.circularSize === 0) {
      return { success: false, reason: 'UNDERFLOW: Circular buffer is empty (0/5).' };
    }
    const item = this.circularQueue[this.circularFront];
    this.circularQueue[this.circularFront] = null;
    this.circularFront = (this.circularFront + 1) % this.circularCap;
    this.circularSize--;
    return { success: true, item };
  }

  // --- Singly Linked List: Driver Catalog ---
  registerDriver(name, location, seats) {
    const driverId = this.idCounter.driver++;
    const newDriver = {
      id: driverId,
      name,
      location,
      seats: parseInt(seats, 10),
      originalSeats: parseInt(seats, 10),
      next: null
    };

    if (!this.driverHead) {
      this.driverHead = newDriver;
    } else {
      let curr = this.driverHead;
      while (curr.next) {
        curr = curr.next;
      }
      curr.next = newDriver;
    }
    this.driverCount++;

    // Insert into Hash Table with Chaining
    const bucketIdx = driverId % this.hashBucketSize;
    this.hashTable[bucketIdx].push(newDriver);

    return newDriver;
  }

  findDriverById(id) {
    const bucketIdx = id % this.hashBucketSize;
    const bucket = this.hashTable[bucketIdx];
    return bucket.find(d => d.id === parseInt(id, 10)) || null;
  }

  // --- Doubly Linked List: Active Confirmed Rides ---
  addActiveRide(passenger, driver, route, dist) {
    const rideId = this.idCounter.ride++;
    const rideNode = {
      rideId,
      passenger,
      driverId: driver.id,
      driverName: driver.name,
      route,
      dist,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      prev: null,
      next: null
    };

    if (!this.activeRidesHead) {
      this.activeRidesHead = rideNode;
      this.activeRidesTail = rideNode;
    } else {
      rideNode.prev = this.activeRidesTail;
      this.activeRidesTail.next = rideNode;
      this.activeRidesTail = rideNode;
    }
    this.activeRideCount++;

    // Decrement driver seat
    driver.seats -= 1;

    // Insert into BST
    this.bstRoot = this.insertBST(this.bstRoot, rideNode);

    // Push into Undo Stack (LIFO)
    this.undoStack.push({
      type: 'CONFIRM_RIDE',
      rideId,
      driverId: driver.id,
      passenger,
      rideNode
    });

    return rideNode;
  }

  removeActiveRide(rideId) {
    let curr = this.activeRidesHead;
    while (curr) {
      if (curr.rideId === rideId) {
        if (curr.prev) curr.prev.next = curr.next;
        else this.activeRidesHead = curr.next;

        if (curr.next) curr.next.prev = curr.prev;
        else this.activeRidesTail = curr.prev;

        this.activeRideCount--;
        // Remove from BST
        this.bstRoot = this.deleteBST(this.bstRoot, rideId);
        return curr;
      }
      curr = curr.next;
    }
    return null;
  }

  // --- Binary Search Tree (BST) Operations ---
  insertBST(root, ride) {
    if (!root) {
      return { rideId: ride.rideId, ride, left: null, right: null };
    }
    if (ride.rideId < root.rideId) {
      root.left = this.insertBST(root.left, ride);
    } else {
      root.right = this.insertBST(root.right, ride);
    }
    return root;
  }

  deleteBST(root, rideId) {
    if (!root) return null;
    if (rideId < root.rideId) {
      root.left = this.deleteBST(root.left, rideId);
    } else if (rideId > root.rideId) {
      root.right = this.deleteBST(root.right, rideId);
    } else {
      // Node found
      if (!root.left) return root.right;
      if (!root.right) return root.left;
      // 2 children: get in-order successor
      let succ = root.right;
      while (succ.left) succ = succ.left;
      root.rideId = succ.rideId;
      root.ride = succ.ride;
      root.right = this.deleteBST(root.right, succ.rideId);
    }
    return root;
  }

  getBSTInOrder(root = this.bstRoot, list = []) {
    if (root) {
      this.getBSTInOrder(root.left, list);
      list.push(root.rideId);
      this.getBSTInOrder(root.right, list);
    }
    return list;
  }

  // --- Stack (LIFO): Undo Mechanism ---
  undoLatestRide() {
    if (this.undoStack.length === 0) {
      return { success: false, reason: 'Undo stack is empty.' };
    }

    const action = this.undoStack.pop();
    if (action.type === 'CONFIRM_RIDE') {
      // 1. Remove from Doubly Linked List & BST
      this.removeActiveRide(action.rideId);

      // 2. Restore driver seat
      const driver = this.findDriverById(action.driverId);
      if (driver) {
        driver.seats = Math.min(driver.seats + 1, driver.originalSeats);
      }

      // 3. Put passenger back to front of Queue
      this.passengerQueue.unshift(action.passenger);

      return { success: true, action };
    }

    return { success: false, reason: 'Unknown stack action.' };
  }
}

// Instantiate Engine
const engine = new SmartCityEngine();

// ==========================================
// 2. 3D INTERACTIVE CITY CANVAS RENDERER
// ==========================================
class City3DCanvas {
  constructor(canvasId) {
    this.canvas = document.getElementById(canvasId);
    this.ctx = this.canvas.getContext('2d');
    this.wrapper = this.canvas.parentElement;

    this.rotX = 0.45;
    this.rotY = -0.3;
    this.scale = 1.05;

    this.isDragging = false;
    this.lastMouseX = 0;
    this.lastMouseY = 0;

    this.highlightedPath = [];
    this.hoveredNode = null;

    this.initEvents();
    this.resize();
    window.addEventListener('resize', () => this.resize());
    this.animate();
  }

  resize() {
    this.width = this.wrapper.clientWidth;
    this.height = this.wrapper.clientHeight;
    this.canvas.width = this.width * window.devicePixelRatio;
    this.canvas.height = this.height * window.devicePixelRatio;
    this.ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
  }

  initEvents() {
    this.canvas.addEventListener('mousedown', (e) => {
      this.isDragging = true;
      this.lastMouseX = e.clientX;
      this.lastMouseY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      this.isDragging = false;
    });

    this.canvas.addEventListener('mousemove', (e) => {
      if (this.isDragging) {
        const deltaX = e.clientX - this.lastMouseX;
        const deltaY = e.clientY - this.lastMouseY;
        this.rotY += deltaX * 0.007;
        this.rotX += deltaY * 0.007;
        // Clamp X tilt
        this.rotX = Math.max(0.1, Math.min(1.2, this.rotX));
        this.lastMouseX = e.clientX;
        this.lastMouseY = e.clientY;
      }
      this.checkHover(e);
    });

    this.canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.scale += e.deltaY * -0.001;
      this.scale = Math.max(0.65, Math.min(1.8, this.scale));
    });
  }

  checkHover(e) {
    const rect = this.canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    let found = null;
    CITY_NODES.forEach(n => {
      const p = this.project(n.x, n.y, n.z);
      const dist = Math.hypot(p.x - mouseX, p.y - mouseY);
      if (dist < 18) {
        found = n;
      }
    });

    this.hoveredNode = found;
    const tooltip = document.getElementById('spatial-tooltip');
    if (found) {
      tooltip.textContent = `📍 [Node ${found.id}] ${found.name} (Z-Elevation: ${found.z}m)`;
      tooltip.style.color = '#00F3FF';
    } else {
      tooltip.textContent = 'Click & drag to orbit 3D city grid. Hover nodes for weights.';
      tooltip.style.color = '#94A3B8';
    }
  }

  project(x, y, z) {
    // 3D rotation matrix projection
    // Rotate Y
    const cosY = Math.cos(this.rotY);
    const sinY = Math.sin(this.rotY);
    const x1 = x * cosY + z * sinY;
    const z1 = -x * sinY + z * cosY;

    // Rotate X
    const cosX = Math.cos(this.rotX);
    const sinX = Math.sin(this.rotX);
    const y2 = y * cosX - z1 * sinX;
    const z2 = y * sinX + z1 * cosX;

    // Perspective factor
    const cameraDist = 420;
    const fov = cameraDist / (cameraDist + z2);

    const screenX = this.width / 2 + x1 * fov * this.scale;
    const screenY = this.height / 2 + y2 * fov * this.scale;

    return { x: screenX, y: screenY, scale: fov, z: z2 };
  }

  setHighlightPath(path) {
    this.highlightedPath = path;
  }

  resetCamera() {
    this.rotX = 0.45;
    this.rotY = -0.3;
    this.scale = 1.05;
  }

  animate() {
    this.render();
    requestAnimationFrame(() => this.animate());
  }

  render() {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);

    // Draw 3D Ground Grid
    this.drawGroundGrid();

    // Draw Edges
    CITY_EDGES.forEach(edge => {
      const uNode = CITY_NODES.find(n => n.id === edge.u);
      const vNode = CITY_NODES.find(n => n.id === edge.v);
      const p1 = this.project(uNode.x, uNode.y, uNode.z);
      const p2 = this.project(vNode.x, vNode.y, vNode.z);

      // Check if edge is in highlighted path
      let isHighlighted = false;
      for (let i = 0; i < this.highlightedPath.length - 1; i++) {
        const a = this.highlightedPath[i];
        const b = this.highlightedPath[i + 1];
        if ((a === edge.u && b === edge.v) || (a === edge.v && b === edge.u)) {
          isHighlighted = true;
          break;
        }
      }

      ctx.save();
      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      ctx.lineTo(p2.x, p2.y);

      if (isHighlighted) {
        ctx.strokeStyle = '#00F3FF';
        ctx.lineWidth = 4.5;
        ctx.shadowColor = '#00F3FF';
        ctx.shadowBlur = 18;
      } else {
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.14)';
        ctx.lineWidth = 2;
      }
      ctx.stroke();
      ctx.restore();

      // Edge Weight Tag
      const midX = (p1.x + p2.x) / 2;
      const midY = (p1.y + p2.y) / 2;
      ctx.save();
      ctx.fillStyle = isHighlighted ? 'rgba(0, 243, 255, 0.95)' : 'rgba(15, 23, 42, 0.85)';
      ctx.strokeStyle = isHighlighted ? '#00FF87' : 'rgba(255, 255, 255, 0.2)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect(midX - 14, midY - 9, 28, 18, 4);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = isHighlighted ? '#070B14' : '#94A3B8';
      ctx.font = 'bold 9px "JetBrains Mono"';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(`${edge.weight}km`, midX, midY);
      ctx.restore();
    });

    // Draw Nodes (Sorted by Z for proper 3D occlusion)
    const sortedNodes = [...CITY_NODES].map(n => ({
      node: n,
      proj: this.project(n.x, n.y, n.z)
    })).sort((a, b) => b.proj.z - a.proj.z);

    sortedNodes.forEach(({ node, proj }) => {
      const isPath = this.highlightedPath.includes(node.id);
      const isHovered = this.hoveredNode && this.hoveredNode.id === node.id;

      ctx.save();

      // Shadow projection onto floor
      const floorProj = this.project(node.x, node.y, -30);
      ctx.beginPath();
      ctx.ellipse(floorProj.x, floorProj.y, 14 * proj.scale, 7 * proj.scale, 0, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
      ctx.fill();

      // Elevation pillar stem
      ctx.beginPath();
      ctx.moveTo(floorProj.x, floorProj.y);
      ctx.lineTo(proj.x, proj.y);
      ctx.strokeStyle = isPath ? 'rgba(0, 243, 255, 0.5)' : 'rgba(255, 255, 255, 0.12)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([2, 3]);
      ctx.stroke();
      ctx.setLineDash([]);

      // 3D Node Glow & Circle
      ctx.beginPath();
      const nodeRadius = (isHovered ? 13 : 10) * proj.scale;
      ctx.arc(proj.x, proj.y, nodeRadius, 0, Math.PI * 2);

      if (isPath) {
        ctx.fillStyle = '#00FF87';
        ctx.shadowColor = '#00FF87';
        ctx.shadowBlur = 20;
      } else if (isHovered) {
        ctx.fillStyle = '#00F3FF';
        ctx.shadowColor = '#00F3FF';
        ctx.shadowBlur = 18;
      } else {
        ctx.fillStyle = '#1E293B';
        ctx.strokeStyle = '#00F3FF';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
      ctx.fill();
      ctx.restore();

      // Node Label
      ctx.save();
      ctx.font = '600 11px "Plus Jakarta Sans"';
      ctx.fillStyle = isPath ? '#00FF87' : '#F8FAFC';
      ctx.textAlign = 'center';
      ctx.fillText(node.name, proj.x, proj.y - 16 * proj.scale);
      ctx.font = '500 9px "JetBrains Mono"';
      ctx.fillStyle = '#94A3B8';
      ctx.fillText(`ID: ${node.id}`, proj.x, proj.y + 20 * proj.scale);
      ctx.restore();
    });
  }

  drawGroundGrid() {
    const ctx = this.ctx;
    const gridSize = 220;
    const step = 44;
    const floorZ = -30;

    ctx.save();
    ctx.strokeStyle = 'rgba(0, 243, 255, 0.05)';
    ctx.lineWidth = 1;

    for (let i = -gridSize; i <= gridSize; i += step) {
      const p1 = this.project(i, -gridSize, floorZ);
      const p2 = this.project(i, gridSize, floorZ);
      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      ctx.lineTo(p2.x, p2.y);
      ctx.stroke();

      const p3 = this.project(-gridSize, i, floorZ);
      const p4 = this.project(gridSize, i, floorZ);
      ctx.beginPath();
      ctx.moveTo(p3.x, p3.y);
      ctx.lineTo(p4.x, p4.y);
      ctx.stroke();
    }
    ctx.restore();
  }
}

// ==========================================
// 3. UI RENDERING & COMPONENT SYNCS
// ==========================================

function updateAllUI() {
  renderQueuePipelines();
  renderCircularBuffer();
  renderDriverFleet();
  renderHashTable();
  renderActiveRides();
