#include <iostream>
#include <vector>
#include <queue>
using namespace std;

typedef pair<int, string> EdgeWeightPair; // <distance, node_id>

struct CityGraph {
    unordered_map<string, vector<pair<string, int>>> adjList;

    void addEdge(const string& u, const string& v, int weight) {
        adjList[u].push_back({v, weight});
        adjList[v].push_back({u, weight});
    }

    void dijkstra(const string& source, const string& dest) {
        priority_queue<EdgeWeightPair, vector<EdgeWeightPair>, greater<EdgeWeightPair>> minHeap;
        unordered_map<string, int> dist;
        unordered_map<string, string> parent;

        for (auto& pair : adjList) dist[pair.first] = INT_MAX;
        dist[source] = 0;
        minHeap.push({0, source});

        while (!minHeap.empty()) {
            int d = minHeap.top().first;
            string u = minHeap.top().second;
            minHeap.pop();

            if (u == dest) break;
            if (d > dist[u]) continue;

            for (auto& edge : adjList[u]) {
                string v = edge.first;
                int weight = edge.second;
                if (dist[u] + weight < dist[v]) {
                    dist[v] = dist[u] + weight;
                    parent[v] = u;
                    minHeap.push({dist[v], v}); // Push relaxed vertex
                }
            }
        }
