class CircularWaitlistQueue {
private:
    Passenger array[5];
    int front = 0;
    int rear = 0;
    int count = 0;
    const int CAPACITY = 5;

public:
    bool isFull() { return count == CAPACITY; }
    bool isEmpty() { return count == 0; }

