    passPickup.insertAdjacentHTML('beforeend', opt);
    passDrop.insertAdjacentHTML('beforeend', opt);
    driverLoc.insertAdjacentHTML('beforeend', opt);
  });

  sourceSel.value = 'ALPHA';
  destSel.value = 'HORIZON';
