  driverLoc.value = 'METRO';

  // --- Run Dijkstra Button ---
  document.getElementById('btn-run-dijkstra').addEventListener('click', () => {
    const src = sourceSel.value;
    const dst = destSel.value;

    if (src === dst) {
      showToast('Source and Destination cannot be the same node.', 'rose');
      return;
    }

    const result = engine.runDijkstra(src, dst);
    cityCanvas.setHighlightPath(result.path);

    const costSummary = document.getElementById('route-cost-summary');
    costSummary.textContent = `Path: ${result.path.join(' -> ')} (Cost: ${result.totalCost} km)`;

    // Render Min-Heap trace strip
    const heapStrip = document.getElementById('minheap-visual-strip');
    heapStrip.innerHTML = result.traceSteps.map((step, idx) => `
      <div class="heap-pill ${idx === 0 ? 'active' : ''}">
        <i class="fa-solid fa-angles-down"></i> Pop: <b>${step.extracted}</b> (${step.dist}km)
        ${step.heapSnapshot.length > 0 ? `<span class="text-slate-400">| Q: [${step.heapSnapshot.map(h => `${h.node}:${h.dist}`).join(', ')}]</span>` : ''}
      </div>
    `).join('');

    showToast(`Dijkstra Min-Heap computed optimal path in ${result.traceSteps.length} relaxation steps.`, 'cyan');
  });

  document.getElementById('btn-reset-graph-cam').addEventListener('click', () => {
    cityCanvas.resetCamera();
  });

  // --- Enqueue Passenger ---
  document.getElementById('btn-enqueue-passenger').addEventListener('click', () => {
