    if (targetCard) targetCard.classList.add('highlight');

    const driver = engine.findDriverById(searchId);
    if (driver) {
      showToast(`Hash O(1) Hit in Bucket [${bucketIdx}]: ${driver.name} (Location: ${driver.location}, Seats: ${driver.seats})`, 'cyan');
    } else {
      showToast(`Hash Search: Driver ID ${searchId} not found in Bucket [${bucketIdx}].`, 'rose');
    }
  });

  // --- Confirm & Match Ride ---
  document.getElementById('btn-match-instant').addEventListener('click', () => {
    // Get passenger (FIFO queue or Circular buffer)
    let passenger = engine.dequeuePassenger();
    if (!passenger && engine.circularSize > 0) {
      passenger = engine.circularDequeue().item;
    }

    if (!passenger) {
      showToast('No passengers waiting in Queue or Circular Buffer to match!', 'rose');
      return;
    }

    // Find available driver
    let matchedDriver = null;
    let curr = engine.driverHead;
    while (curr) {
      if (curr.seats > 0) {
        matchedDriver = curr;
        break;
      }
      curr = curr.next;
    }

    if (!matchedDriver) {
      // Put passenger back
      engine.passengerQueue.unshift(passenger);
      showToast('All registered drivers are full or fleet is empty. Register a driver first!', 'rose');
      return;
    }

    // Compute route distance with Dijkstra
    const routeRes = engine.runDijkstra(passenger.pickup, passenger.drop);
    const ride = engine.addActiveRide(passenger, matchedDriver, routeRes.path, routeRes.totalCost);

    cityCanvas.setHighlightPath(routeRes.path);
    updateAllUI();
    showToast(`Ride #${ride.rideId} matched! Inserted into Doubly LL, BST, and Stack.`, 'purple');
  });

  // --- Undo Ride (Stack Pop) ---
  document.getElementById('btn-undo-ride').addEventListener('click', () => {
    const res = engine.undoLatestRide();
    if (!res.success) {
      showToast(res.reason, 'rose');
    } else {
      showToast(`Undone Ride #${res.action.rideId}: Restored driver #${res.action.driverId} seats & pushed passenger back to Queue.`, 'rose');
      updateAllUI();
    }
  });

  // --- Preset City Demo Loader ---
  document.getElementById('btn-demo-preset').addEventListener('click', () => {
    // Pre-populate with realistic city traffic
    engine.registerDriver('Marcus Vance', 'ALPHA', 3);
    engine.registerDriver('Elena Rostova', 'METRO', 4);
    engine.registerDriver('Kaelen Chen', 'SKYPORT', 2);
    engine.registerDriver('Siddharth Rao', 'QUANTUM', 4);

    engine.enqueuePassenger('Sarah Connor', 'ALPHA', 'HORIZON');
    engine.enqueuePassenger('Liam Dawson', 'METRO', 'SKYPORT');
    engine.enqueuePassenger('Amara Okafor', 'HARBOR', 'QUANTUM');

    engine.circularEnqueue({
      id: 'P-CIRC-01',
      name: 'Waitlist Taro',
      pickup: 'HARBOR',
      drop: 'HORIZON',
      timestamp: new Date().toLocaleTimeString()
    });

    // Run sample match
    const p1 = engine.dequeuePassenger();
    const d1 = engine.driverHead;
    const r1 = engine.runDijkstra(p1.pickup, p1.drop);
    engine.addActiveRide(p1, d1, r1.path, r1.totalCost);

    cityCanvas.setHighlightPath(r1.path);
    updateAllUI();
    showToast('Loaded dynamic city scenario with live drivers, queues, and matched routes!', 'emerald');
  });

  // --- Code Inspector Drawer Tabs ---
  const codeOverlay = document.getElementById('code-drawer-overlay');
  const codeDisplay = document.getElementById('code-display');
  const tabBtns = document.querySelectorAll('.tab-btn');

  document.getElementById('btn-toggle-cpp-code').addEventListener('click', () => {
    codeOverlay.classList.remove('hidden');
    codeDisplay.textContent = CPP_CODE_SNIPPETS['tab-graph'];
  });

  document.getElementById('btn-close-drawer').addEventListener('click', () => {
    codeOverlay.classList.add('hidden');
  });

  codeOverlay.addEventListener('click', (e) => {
    if (e.target === codeOverlay) codeOverlay.classList.add('hidden');
  });

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      tabBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const tabKey = btn.dataset.tab;
      codeDisplay.textContent = CPP_CODE_SNIPPETS[tabKey] || '// Code snippet loading...';
    });
  });

  // Initial UI Render & Tilt Bind
  updateAllUI();
  bindTiltElements();
});

