/* ==========================================================================
   NEXUSMOBILITY — ENTERPRISE URBAN CARPOOLING & ECO-LOGISTICS PLATFORM
   Clean Corporate Dark Theme, Micro-Glassmorphism, & 3D Tilt Physics
   ========================================================================== */

:root {
  --navy-deep: #0B172A;
  --navy-surface: rgba(15, 23, 42, 0.78);
  --navy-surface-hover: rgba(22, 33, 58, 0.9);
  --navy-border: rgba(52, 120, 246, 0.16);
  --navy-border-hover: rgba(32, 201, 176, 0.45);

  --mint: #20C9B0;
  --mint-glow: rgba(32, 201, 176, 0.35);
  --electric: #3478F6;
  --electric-glow: rgba(52, 120, 246, 0.35);
  --purple: #A855F7;
  --purple-glow: rgba(168, 85, 247, 0.35);
  --amber: #F59E0B;
  --amber-glow: rgba(245, 158, 11, 0.35);
  --rose: #F43F5E;
  --rose-glow: rgba(244, 63, 94, 0.35);

  --slate-50: #F8FAFC;
  --slate-100: #F1F5F9;
  --slate-200: #E2E8F0;
  --slate-300: #CBD5E1;
  --slate-400: #94A3B8;
  --slate-500: #64748B;
  --slate-600: #475569;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--navy-deep);
  color: var(--slate-100);
  font-family: var(--font-sans);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
  perspective: 1200px;
  line-height: 1.5;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: rgba(11, 23, 42, 0.9);
}
::-webkit-scrollbar-thumb {
  background: rgba(52, 120, 246, 0.35);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--mint);
}

/* --------------------------------------------------------------------------
   Layout Shell & Micro-Glassmorphism
   -------------------------------------------------------------------------- */
.app-layout {
  max-width: 1720px;
  margin: 0 auto;
  padding: 1.25rem 1.75rem 3rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.glass-panel {
  background: var(--navy-surface);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid var(--navy-border);
  border-radius: 14px;
  box-shadow: 0 12px 32px -8px rgba(0, 0, 0, 0.65), 0 0 1px 1px rgba(255, 255, 255, 0.04) inset;
  transition: border-color 0.28s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.28s cubic-bezier(0.16, 1, 0.3, 1), transform 0.15s ease-out;
  position: relative;
}

/* 3D Anti-Gravity Tilt Physics Effect */
.tilt-element {
  transform-style: preserve-3d;
  will-change: transform;
}

.tilt-element:hover {
  border-color: var(--navy-border-hover);
  box-shadow: 0 20px 45px -10px rgba(32, 201, 176, 0.14), 0 0 25px rgba(52, 120, 246, 0.1);
}

/* --------------------------------------------------------------------------
   Top Navigation
   -------------------------------------------------------------------------- */
.top-nav {
  padding: 0.85rem 1.75rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.nav-left {
  display: flex;
  align-items: center;
  gap: 2.25rem;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  text-decoration: none;
}

.brand-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(32, 201, 176, 0.25), rgba(52, 120, 246, 0.2));
  border: 1px solid var(--mint);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  box-shadow: 0 0 15px var(--mint-glow);
}

.brand-name {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #FFFFFF;
}

.brand-tagline {
  font-size: 0.62rem;
  font-family: var(--font-mono);
  letter-spacing: 0.12em;
  color: var(--slate-400);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.25rem;
}

.nav-link {
  color: var(--slate-300);
  text-decoration: none;
  font-size: 0.85rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.4rem 0.65rem;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.nav-link:hover, .nav-link.active {
  color: #FFFFFF;
  background: rgba(255, 255, 255, 0.06);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* --------------------------------------------------------------------------
   Buttons & Form Controls
   -------------------------------------------------------------------------- */
.btn {
  font-family: var(--font-sans);
  font-size: 0.825rem;
  font-weight: 600;
  padding: 0.55rem 1.05rem;
  border-radius: 9px;
  border: 1px solid transparent;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
  white-space: nowrap;
}

.btn-primary {
  background: linear-gradient(135deg, #3478F6, #2055C4);
  color: #FFFFFF;
  box-shadow: 0 4px 14px rgba(52, 120, 246, 0.35);
}
.btn-primary:hover {
  background: linear-gradient(135deg, #4A8BF9, #3478F6);
  box-shadow: 0 6px 20px rgba(52, 120, 246, 0.5);
  transform: translateY(-2px);
}

.btn-mint {
  background: rgba(32, 201, 176, 0.14);
  border-color: var(--mint);
  color: var(--mint);
  box-shadow: 0 0 12px rgba(32, 201, 176, 0.2);
}
.btn-mint:hover {
  background: var(--mint);
  color: #0B172A;
  box-shadow: 0 0 22px var(--mint-glow);
  transform: translateY(-2px);
}

.btn-amber {
  background: rgba(245, 158, 11, 0.15);
  border-color: var(--amber);
  color: var(--amber);
}
.btn-amber:hover {
  background: var(--amber);
  color: #0B172A;
  transform: translateY(-2px);
}

.btn-rose {
  background: rgba(244, 63, 94, 0.15);
  border-color: var(--rose);
  color: #FDA4AF;
}
.btn-rose:hover {
  background: var(--rose);
  color: #FFFFFF;
  box-shadow: 0 0 20px var(--rose-glow);
  transform: translateY(-2px);
}

.btn-outline {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: var(--slate-200);
}
.btn-outline:hover {
  background: rgba(255, 255, 255, 0.09);
  border-color: rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
}

.btn-ghost {
  background: transparent;
  color: var(--slate-400);
}
.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #FFFFFF;
}

.btn-sm {
  padding: 0.35rem 0.65rem;
  font-size: 0.74rem;
}

.text-input, .select-field {
  background: rgba(11, 23, 42, 0.85);
  border: 1px solid rgba(52, 120, 246, 0.25);
  border-radius: 8px;
  color: #FFFFFF;
  padding: 0.55rem 0.8rem;
  font-size: 0.825rem;
  font-family: var(--font-sans);
  outline: none;
  transition: all 0.2s ease;
  width: 100%;
}

.text-input:focus, .select-field:focus {
  border-color: var(--mint);
  box-shadow: 0 0 12px var(--mint-glow);
}

.text-input::placeholder {
  color: var(--slate-500);
}

.input-with-icon {
  position: relative;
  display: flex;
  align-items: center;
}

.input-with-icon i {
  position: absolute;
  left: 0.8rem;
  color: var(--slate-400);
  font-size: 0.85rem;
  pointer-events: none;
}

.input-with-icon input {
  padding-left: 2.2rem;
}

/* --------------------------------------------------------------------------
   Executive Summary / KPI Banner
   -------------------------------------------------------------------------- */
.kpi-banner {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1rem;
}

@media (max-width: 1300px) {
  .kpi-banner {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (max-width: 800px) {
  .kpi-banner {
    grid-template-columns: 1fr;
  }
}

.kpi-card {
  background: var(--navy-surface);
  border: 1px solid var(--navy-border);
  border-radius: 12px;
  padding: 1rem 1.25rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  box-shadow: 0 6px 20px -5px rgba(0, 0, 0, 0.5);
}

.kpi-icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.bg-mint-glow { background: rgba(32, 201, 176, 0.15); border: 1px solid rgba(32, 201, 176, 0.3); }
.bg-blue-glow { background: rgba(52, 120, 246, 0.15); border: 1px solid rgba(52, 120, 246, 0.3); }
.bg-purple-glow { background: rgba(168, 85, 247, 0.15); border: 1px solid rgba(168, 85, 247, 0.3); }
.bg-amber-glow { background: rgba(245, 158, 11, 0.15); border: 1px solid rgba(245, 158, 11, 0.3); }
.bg-emerald-glow { background: rgba(16, 185, 129, 0.15); border: 1px solid rgba(16, 185, 129, 0.3); }

.kpi-label {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--slate-400);
