// ==========================================
// 1. METROPOLITAN TRANSIT STATIONS & NETWORK
// ==========================================
const TRANSIT_STATIONS = [
  { id: 'ALPHA', name: 'Tech Park Alpha', x: -160, y: -70, z: 20, zone: 'North Industrial' },
  { id: 'HARBOR', name: 'Bayfront Terminal', x: -80, y: 110, z: -15, zone: 'Maritime District' },
  { id: 'METRO', name: 'Central Financial Core', x: 0, y: 0, z: 40, zone: 'Downtown Metro' },
  { id: 'SKYPORT', name: 'AeroPort Interchange', x: 130, y: -90, z: 30, zone: 'Aviation Corridor' },
  { id: 'QUANTUM', name: 'Green Innovation Campus', x: 90, y: 100, z: -10, zone: 'Eco District' },
  { id: 'HORIZON', name: 'Waterfront Marina', x: 200, y: 30, z: 5, zone: 'East Residential' }
];

// Transit Corridors with distances (km)
const TRANSIT_CORRIDORS = [
  { u: 'ALPHA', v: 'METRO', distance: 8.2 },
  { u: 'ALPHA', v: 'HARBOR', distance: 11.5 },
  { u: 'HARBOR', v: 'METRO', distance: 6.4 },
