const engine = new NexusTransitEngine();

// ==========================================
// 3. 3D SPATIAL METROPOLITAN CANVAS MAP
// ==========================================
class Urban3DCanvas {
  constructor(canvasId) {
    this.canvas = document.getElementById(canvasId);
    this.ctx = this.canvas.getContext('2d');
    this.wrapper = this.canvas.parentElement;

    this.rotX = 0.45;
    this.rotY = -0.32;
    this.scale = 1.08;

    this.isDragging = false;
    this.lastMouseX = 0;
    this.lastMouseY = 0;

    this.activeCorridorPath = [];
    this.hoveredStation = null;

    this.initEvents();
    this.resize();
    window.addEventListener('resize', () => this.resize());
    this.animate();
  }

  resize() {
    this.width = this.wrapper.clientWidth;
    this.height = this.wrapper.clientHeight;
    this.canvas.width = this.width * window.devicePixelRatio;
    this.canvas.height = this.height * window.devicePixelRatio;
    this.ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
  }

  initEvents() {
    this.canvas.addEventListener('mousedown', (e) => {
      this.isDragging = true;
      this.lastMouseX = e.clientX;
      this.lastMouseY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      this.isDragging = false;
    });

    this.canvas.addEventListener('mousemove', (e) => {
      if (this.isDragging) {
        const deltaX = e.clientX - this.lastMouseX;
        const deltaY = e.clientY - this.lastMouseY;
        this.rotY += deltaX * 0.007;
        this.rotX += deltaY * 0.007;
        this.rotX = Math.max(0.12, Math.min(1.2, this.rotX));
        this.lastMouseX = e.clientX;
        this.lastMouseY = e.clientY;
      }
      this.checkHover(e);
    });

    this.canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.scale += e.deltaY * -0.001;
      this.scale = Math.max(0.65, Math.min(1.85, this.scale));
    });
  }

  checkHover(e) {
    const rect = this.canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    let found = null;
    TRANSIT_STATIONS.forEach(s => {
      const p = this.project(s.x, s.y, s.z);
      const dist = Math.hypot(p.x - mouseX, p.y - mouseY);
      if (dist < 20) {
        found = s;
      }
    });

    this.hoveredStation = found;
    const hud = document.getElementById('map-hud-overlay');
    if (found) {
      hud.innerHTML = `<span class="text-mint font-bold">📍 ${found.name}</span> &bull; Transit Zone: ${found.zone} &bull; Corridor Elevation: +${found.z}m`;
    } else {
      hud.innerHTML = `<i class="fa-solid fa-hand-pointer text-mint"></i> Click & drag to orbit 3D city corridors &bull; Scroll to zoom`;
    }
  }

  project(x, y, z) {
    const cosY = Math.cos(this.rotY);
    const sinY = Math.sin(this.rotY);
    const x1 = x * cosY + z * sinY;
    const z1 = -x * sinY + z * cosY;

    const cosX = Math.cos(this.rotX);
    const sinX = Math.sin(this.rotX);
    const y2 = y * cosX - z1 * sinX;
    const z2 = y * sinX + z1 * cosX;

    const cameraDist = 440;
    const fov = cameraDist / (cameraDist + z2);

    const screenX = this.width / 2 + x1 * fov * this.scale;
    const screenY = this.height / 2 + y2 * fov * this.scale;

    return { x: screenX, y: screenY, scale: fov, z: z2 };
  }

  setActivePath(path) {
    this.activeCorridorPath = path;
  }

  resetCamera() {
    this.rotX = 0.45;
    this.rotY = -0.32;
    this.scale = 1.08;
  }

  animate() {
    this.render();
    requestAnimationFrame(() => this.animate());
  }

  render() {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);

    // Draw Ground Arterial Grid
    this.drawGroundGrid();

    // Draw Transit Corridors
    TRANSIT_CORRIDORS.forEach(corridor => {
      const uStation = TRANSIT_STATIONS.find(s => s.id === corridor.u);
      const vStation = TRANSIT_STATIONS.find(s => s.id === corridor.v);
      const p1 = this.project(uStation.x, uStation.y, uStation.z);
      const p2 = this.project(vStation.x, vStation.y, vStation.z);

      let isPath = false;
      for (let i = 0; i < this.activeCorridorPath.length - 1; i++) {
        const a = this.activeCorridorPath[i];
        const b = this.activeCorridorPath[i + 1];
        if ((a === corridor.u && b === corridor.v) || (a === corridor.v && b === corridor.u)) {
          isPath = true;
          break;
        }
      }

      ctx.save();
      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      ctx.lineTo(p2.x, p2.y);

      if (isPath) {
        ctx.strokeStyle = '#3478F6';
        ctx.lineWidth = 4.5;
        ctx.shadowColor = '#3478F6';
        ctx.shadowBlur = 18;
      } else {
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.14)';
        ctx.lineWidth = 1.75;
      }
      ctx.stroke();
      ctx.restore();

      // Corridor Distance Tag
      const midX = (p1.x + p2.x) / 2;
      const midY = (p1.y + p2.y) / 2;
      ctx.save();
      ctx.fillStyle = isPath ? 'rgba(52, 120, 246, 0.95)' : 'rgba(11, 23, 42, 0.85)';
      ctx.strokeStyle = isPath ? '#20C9B0' : 'rgba(255, 255, 255, 0.18)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect(midX - 16, midY - 9, 32, 18, 4);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = isPath ? '#FFFFFF' : '#94A3B8';
      ctx.font = 'bold 9px "JetBrains Mono"';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(`${corridor.distance}km`, midX, midY);
      ctx.restore();
    });

    // Draw Stations (Sorted by Z for proper 3D depth)
    const sorted = [...TRANSIT_STATIONS].map(s => ({
      station: s,
      proj: this.project(s.x, s.y, s.z)
    })).sort((a, b) => b.proj.z - a.proj.z);

    sorted.forEach(({ station, proj }) => {
      const isPath = this.activeCorridorPath.includes(station.id);
      const isHovered = this.hoveredStation && this.hoveredStation.id === station.id;

      ctx.save();

      // Floor Shadow
      const floorProj = this.project(station.x, station.y, -30);
      ctx.beginPath();
      ctx.ellipse(floorProj.x, floorProj.y, 14 * proj.scale, 7 * proj.scale, 0, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
      ctx.fill();

      // Elevation Stem
      ctx.beginPath();
      ctx.moveTo(floorProj.x, floorProj.y);
      ctx.lineTo(proj.x, proj.y);
      ctx.strokeStyle = isPath ? 'rgba(32, 201, 176, 0.5)' : 'rgba(255, 255, 255, 0.12)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([2, 3]);
      ctx.stroke();
      ctx.setLineDash([]);

      // Station Hub Circle
      ctx.beginPath();
      const radius = (isHovered ? 13 : 10) * proj.scale;
      ctx.arc(proj.x, proj.y, radius, 0, Math.PI * 2);

      if (isPath) {
        ctx.fillStyle = '#20C9B0';
        ctx.shadowColor = '#20C9B0';
        ctx.shadowBlur = 18;
      } else if (isHovered) {
        ctx.fillStyle = '#3478F6';
        ctx.shadowColor = '#3478F6';
        ctx.shadowBlur = 16;
      } else {
        ctx.fillStyle = '#1E293B';
        ctx.strokeStyle = '#20C9B0';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
      ctx.fill();
      ctx.restore();

      // Station Label
      ctx.save();
      ctx.font = '600 11px "Inter"';
      ctx.fillStyle = isPath ? '#20C9B0' : '#F8FAFC';
      ctx.textAlign = 'center';
      ctx.fillText(station.name, proj.x, proj.y - 16 * proj.scale);
      ctx.font = '500 9px "JetBrains Mono"';
      ctx.fillStyle = '#94A3B8';
      ctx.fillText(station.zone, proj.x, proj.y + 19 * proj.scale);
      ctx.restore();
    });
  }

  drawGroundGrid() {
    const ctx = this.ctx;
    const size = 220;
    const step = 44;
    const floorZ = -30;

    ctx.save();
    ctx.strokeStyle = 'rgba(52, 120, 246, 0.06)';
    ctx.lineWidth = 1;

    for (let i = -size; i <= size; i += step) {
      const p1 = this.project(i, -size, floorZ);
      const p2 = this.project(i, size, floorZ);
      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      ctx.lineTo(p2.x, p2.y);
      ctx.stroke();

      const p3 = this.project(-size, i, floorZ);
      const p4 = this.project(size, i, floorZ);
      ctx.beginPath();
      ctx.moveTo(p3.x, p3.y);
      ctx.lineTo(p4.x, p4.y);
      ctx.stroke();
    }
    ctx.restore();
  }
}

