function refreshPlatformUI() {
  renderPassengerDispatchStream();
  renderStandbyLounge();
  renderFleetDirectory();
  renderActiveTrips();
  renderTransitHierarchyCanvas();
  renderAuditHistory();
  renderLeaderboard();
  updateTopKPIs();
