// ==========================================
// 5. 3D ANTI-GRAVITY PERSPECTIVE TILT
// ==========================================
function bind3DTilt() {
  const elements = document.querySelectorAll('[data-tilt]');
  elements.forEach(el => {
    if (el._tiltAttached) return;
    el._tiltAttached = true;

    el.addEventListener('mousemove', (e) => {
      const rect = el.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const centerX = rect.width / 2;
      const centerY = rect.height / 2;

      // Subtle tilt angles (-8 to 8 deg)
      const rotateX = ((centerY - y) / centerY) * 7.5;
      const rotateY = ((x - centerX) / centerX) * 7.5;

      el.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateZ(10px)`;
    });

    el.addEventListener('mouseleave', () => {
      el.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) translateZ(0px)';
    });
  });
}

// ==========================================
// 6. TOAST NOTIFICATIONS
// ==========================================
function showPlatformToast(message, type = 'emerald') {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;
  toast.innerHTML = `<i class="fa-solid fa-circle-check text-emerald"></i><span>${message}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(15px)';
    setTimeout(() => toast.remove(), 300);
  }, 3600);
}

