// ==========================================
// 4. MULTI-TAB SWITCHING CONTROLLER
// ==========================================
function initTabNavigation() {
  const triggers = document.querySelectorAll('.tab-trigger');
  const views = document.querySelectorAll('.tab-view');

  triggers.forEach(trigger => {
    trigger.addEventListener('click', () => {
      const targetTabId = trigger.dataset.tab;

      // Update triggers
      triggers.forEach(t => t.classList.remove('active'));
      trigger.classList.add('active');

      // Update views
      views.forEach(v => {
        v.classList.remove('active');
        if (v.id === targetTabId) {
          v.classList.add('active');
        }
      });

      // If switched to Map, trigger canvas resize and redraw
      if (targetTabId === 'tab-route-finder' && urbanCanvasInstance) {
        setTimeout(() => {
          urbanCanvasInstance.resize();
        }, 50);
      }

      // Rebind 3D tilt to visible cards
      rebind3DTilt();
    });
  });
}

